struct WorldDamageData::State {WorldDamagePolicy policy;std::vector<WorldDamageClip>clips;std::vector<WorldDamageKey>keys;std::vector<WorldDamageStatus>statuses;};
const WorldDamagePolicy&WorldDamageData::policy()const{static const WorldDamagePolicy empty;return state_?state_->policy:empty;}
const std::vector<WorldDamageClip>&WorldDamageData::clips()const{static const std::vector<WorldDamageClip>empty;return state_?state_->clips:empty;}
const std::vector<WorldDamageKey>&WorldDamageData::keys()const{static const std::vector<WorldDamageKey>empty;return state_?state_->keys:empty;}
const std::vector<WorldDamageStatus>&WorldDamageData::statuses()const{static const std::vector<WorldDamageStatus>empty;return state_?state_->statuses:empty;}
const WorldDamageClip*WorldDamageData::clip(uint32_t id)const{for(const auto&c:clips())if(c.id==id)return &c;return nullptr;}
const WorldDamageStatus*WorldDamageData::status(const std::string&id)const{for(const auto&s:statuses())if(s.id==id)return &s;return nullptr;}
bool WorldDamageData::load_file(const char*name,std::string&e){if(valid()||!name||!*name)return bad(e,"World damage fresh owner/path required");std::vector<uint8_t>b;return encore::read_file(name,b,32768,e)&&load(b.data(),b.size(),e);}
