bool WorldDamageActor::owner(uint64_t epoch,uint64_t instance,std::string&e)const{return valid()&&epoch==epoch_&&instance==instance_?true:bad(e,"World damage stale actor/epoch rejected");}
bool WorldDamageActor::member(const SessionCharacter&c,std::string&e)const{if(c.character_id!=character_||c.hp<0||c.hp>1000000||c.status.size()>data_.statuses().size())return bad(e,"World damage character/HP/status bounds rejected");std::set<std::string>seen;uint32_t priority=UINT32_MAX;for(const auto&v:c.status){auto s=data_.status(v.status_id);if(!s||!seen.insert(v.status_id).second||s->priority>priority||((s->flags&4)&&c.status.size()!=1)||v.passive_healing_turns<0||(!(s->flags&2)&&v.passive_healing_turns))return bad(e,"World damage unsupported/duplicate/unsorted status rejected");priority=s->priority;}return true;}
bool WorldDamageActor::request(const WorldDamageRequest&r,bool explicit_lethality,std::string&e)const{return r.damage>=-1000000&&r.damage<=1000000&&r.variance>=0&&r.variance<=1000000&&finite(r.hit)&&r.hit.x==0&&r.hit.y==0&&unsigned(r.lethality)<=2&&(!explicit_lethality||r.lethality!=WorldDamageLethality::Unspecified)?true:bad(e,"World damage request domain rejected");}
bool WorldDamageActor::prepare_after_reset(const WorldDamageData&data,uint64_t epoch,uint64_t instance,const SessionCharacter&c,std::string&e){if(valid()||!data.valid()||!epoch||epoch<=last_epoch_||!instance||c.character_id.empty())return bad(e,"World damage fresh actor/source/epoch required");WorldDamageActor next;next.data_=data;next.character_=c.character_id;next.epoch_=next.last_epoch_=epoch;next.instance_=instance;if(!next.member(c,e))return false;next.pose_.assigned=data.policy().reset;const auto*reset=data.clip(data.policy().reset);for(uint32_t n=reset->first;n<reset->first+reset->count;++n){const auto&k=data.keys()[n];next.pose_.property[k.target-1]=k.value;}next.pose_.time=reset->duration;*this=std::move(next);e.clear();return true;}
bool WorldDamageActor::play(uint64_t epoch,uint64_t instance,uint32_t clip,std::string&e){if(!owner(epoch,instance,e))return false;const auto*c=data_.clip(clip);if(!c)return bad(e,"World damage unknown flash clip rejected");if(pose_.assigned!=clip||pose_.time==c->duration)pose_.time=0;pose_.assigned=clip;pose_.playing=true;e.clear();return true;}
bool WorldDamageActor::pause_flash(uint64_t epoch,uint64_t instance,std::string&e){if(!owner(epoch,instance,e))return false;if(invulnerable())pose_.playing=false;else return play(epoch,instance,data_.policy().reset,e);e.clear();return true;}
bool WorldDamageActor::resume_flash(uint64_t epoch,uint64_t instance,std::string&e){if(!owner(epoch,instance,e))return false;const auto*c=data_.clip(pose_.assigned);if(pose_.assigned==data_.policy().flash&&pose_.time>0&&pose_.time<c->duration)pose_.playing=true;e.clear();return true;}
